INSERT INTO spotlights
  (type, month, status, name, discogs_id, subtitle, meta, bio, releases, collector_notes, neighbors, rekoodos_pick)
VALUES (
  'label',
  '2026-11',
  'active',
  'Sacred Bones Records',
  '155151',
  $str$Brooklyn independent label founded by Caleb Braaten in 2007. Sacred Bones began with records by friends in New York's underground scene and grew into a wide-ranging catalogue spanning post-punk, electronic music, experimental rock, folk, and film scores.$str$,
  $json${"founded": "2007", "location": "Brooklyn, New York", "website": "sacredbonesrecords.com"}$json$::jsonb,
  $json$["Caleb Braaten founded Sacred Bones Records in Brooklyn in 2007 while working at Academy Records in Williamsburg. The label began with 7-inch records by bands in his circle, including The Hunt, Blank Dogs, and Gary War. It also reissued hard-to-find records by early-1980s British post-punk groups such as 13th Chime and Cultural Decay. For its first four years, the label operated from the basement of Academy Records.", "Zola Jesus became an early cornerstone of the catalogue. Braaten signed Nika Roza Danilova's project in 2008; *The Spoils* followed in 2009, then the *Stridulum* EP in 2010 and *Conatus* in 2011. Her electronic arrangements and classically trained vocals helped establish one strand of the label's sound. Moon Duo's *Escape*, released around the same period, brought a motorik, psychedelic approach. The early catalogue set a mood without locking the label into one genre.", "Sacred Bones expanded its range through the 2010s. Marissa Nadler's *July* (2014) brought intimate, guitar-led songwriting into the catalogue. In 2015, John Carpenter released *Lost Themes*, an album of instrumental music made with his son Cody Carpenter and Daniel Davies. It drew on the synthesizer sounds of Carpenter's film scores. Brooklyn industrial duo Uniform added a harsher edge with *The Long Walk* in 2018.", "The label's catalogue has continued to move between new work, reissues, soundtracks, and collaborations. In 2020, Sacred Bones reissued Molchat Doma's *Etazhi*, originally released by Berlin's Detriti Records in 2018. The band's first album for Sacred Bones, *Monument*, came out later that year.", "In October 2025, Sacred Bones entered a strategic partnership with All Flowers Group, an affiliate of Secretly Group. Founder Caleb Braaten joined All Flowers Group's executive leadership, while Sacred Bones continued its existing operations."]$json$::jsonb,
  $json$[{"year": "2009", "title": "The Spoils", "artist": "Zola Jesus", "note": "One of the label's early defining releases. Danilova's voice sits over sparse electronic arrangements, setting a template that subsequent records developed in different directions.", "badge": null}, {"year": "2010", "title": "Stridulum", "artist": "Zola Jesus", "note": "A six-track EP that deepened the dark, layered electronic sound of *The Spoils*. The EP was later collected with *Valusia* on *Stridulum II*.", "badge": "EP"}, {"year": "2011", "title": "Conatus", "artist": "Zola Jesus", "note": "A fuller, more expansive Zola Jesus album, while retaining the layered electronics and prominent vocals of her earlier work. Sacred Bones catalogue number SBR062.", "badge": null}, {"year": "2014", "title": "July", "artist": "Marissa Nadler", "note": "A guitar-led album that brought Nadler's restrained songwriting and close, expressive vocals into the Sacred Bones catalogue.", "badge": null}, {"year": "2015", "title": "Lost Themes", "artist": "John Carpenter, Cody Carpenter & Daniel Davies", "note": "Instrumental music made outside a film commission, built around the synthesizer language associated with Carpenter's scores.", "badge": null}, {"year": "2020", "title": "Etazhi", "artist": "Molchat Doma", "note": "Originally released by Detriti Records in 2018, the album was reissued by Sacred Bones in North America in 2020. Its post-punk arrangements, synth bass, and Russian-language vocals brought the Belarusian trio to a broader audience.", "badge": "Reissue"}, {"year": "2020", "title": "Monument", "artist": "Molchat Doma", "note": "The trio's first album released directly through Sacred Bones. It expanded on the sound of *Etazhi* with a more layered, polished production. Released November 13, 2020.", "badge": null}, {"year": "2026", "title": "Marathon", "artist": "Maria BC", "note": "Maria BC's third studio album and second release for Sacred Bones. Built around themes of endurance, resistance, and survival, it ranges from intimate songwriting to more driving, layered arrangements. Released February 27, 2026.", "badge": null}]$json$::jsonb,
  $json$[{"title": "Original Pressings and Reissues", "body": "Sacred Bones uses SBR catalogue numbers for many releases, which can help identify a particular edition. Early records were often released in smaller runs, and later reissues make some titles easier to find. Check the label, catalogue number, and pressing details against the specific edition you're considering; a title alone may not distinguish an original from a reissue.\n\nThe Sacred Bones Record Society is the label's vinyl club. Membership editions can include limited colour vinyl, an artist-curated mixtape, a certificate of authenticity, and a numbered, wax-stamped wrap. The contents and terms vary by installment, so check the label's listing for the specific membership edition."}, {"title": "Collecting Strategy", "body": "For a starting point, *The Spoils* and *Stridulum* show the label's early electronic and post-punk interests. *July* offers a quieter guitar-led counterpoint, while *Etazhi* and *Monument* trace Molchat Doma's transition from an independent European release to a label-backed international audience. When comparing copies, use the catalogue number and edition details rather than colour alone."}]$json$::jsonb,
  $json$[{"tag": "Sonic Neighbour", "artist": "Drab Majesty", "album": "Modern Mirror (Dais Records, 2019)", "reason": "Dais Records is another independent label with a catalogue that includes darkwave, gothic rock, and electronic music. Drab Majesty's *Modern Mirror* shares some of the cool synthesizer textures and controlled atmosphere found in parts of the Sacred Bones catalogue. The connection is musical rather than organisational."}, {"tag": "Label Context", "artist": "Zola Jesus", "album": "Taiga (Mute Records, 2014)", "reason": "After releasing several records through Sacred Bones, Zola Jesus released *Taiga* on Mute Records in 2014. Its fuller arrangements offer a useful point of comparison with the earlier Sacred Bones releases. Mute is an established independent label, and the move marks a change in label context for Danilova's work."}, {"tag": "Sonic Neighbour", "artist": "She Past Away", "album": "Belirdi Gece (Fabrika Records, 2012)", "reason": "The Turkish duo's *Belirdi Gece* pairs drum machines and synthesizers with minimal guitar and vocals in Turkish. Its cold post-punk approach makes it a natural adjacent listen for fans of Molchat Doma and the darker electronic side of Sacred Bones. The connection is aesthetic; the labels have no formal relationship."}]$json$::jsonb,
  'Marathon'
);
